#include <stdio.h>
#define MAX_SIZE 500

void findLength(char *s, int *p);
// The function saves the length of the string s to the integer pointed by p.
// You are not allowed to make any variable declarations.

void isAllLowerChars(char *s, int *p);
// The function checks if the string s consists of only lower-case alphabet characters or not.
// If it is, the function sets the integer pointed by p to 1. Otherwise, it sets the integer pointed by p to 0.
// You are not allowed to make any variable declarations.

void findCharFirstLoc(char *s, char c, char **p);
/* The function makes a search on the string s and saves the address of the first occurrence of the
character c to the variable pointed by p. */
// If there is no such character in the string, it sets NULL to the variable pointed by p.
// You are not allowed to make any variable declarations.

int main(int argc, char *argv[]);
// The function creates a char array s with size MAX_SIZE.
// The function gets a string and a char from the user and saves them to variables s and c respectively.
/* Then, it checks whether s consists of only lower characters using isAllLowerChars and c is a lower
character. */
// If they are not, it asks the user to enter s and c again until desired inputs are obtained.
// You can assume that there is no space character in the string.
/* The function splits s into tokens by using char c as delimiter and display each token and its length as
given in below algorithm using functions findCharFirstLoc and findLength. */
// Space complexity of the split must be O(1) meaning that you cannot use additional arrays.
// You are allowed to use at most 2 loops.

Algorithm:
Save the address of the beginning of the string s into a pointer, call it p.
REPEAT
       Find the address of the next first occurrence of c.
      Set the value in the found address to the null character.
        Print string starting from the location p and its size.
      Set p to the address of the character just after the found character.
UNTIL no address of c is found
Print string starting from the location p and its size.

