Question 4
#include <stdio.h>
#include <stdlib.h>

void swap(int** x, int** y);
// Variables x and y point to positive int arrays. The function swaps the variables pointed by x and y.
// You are allowed to make only 1 pointer declaration.

void str2int(char** str, int* ptr);
// The function saves int equivalent of the string pointed by str to the variable pointed by ptr.
// You can assume the string consists of only digits and is always positive integer.
// You are allowed to make only 1 pointer declaration.

void addressOfMax(int* A, const int N, int** ptr);
/* The function makes a search on positive int array A with size N and saves the address of the element
with the maximum value to the memory pointed by ptr. You can assume that array has at least one
element. */
// You are allowed to make only 1 pointer declaration.

void indexOfMax(int** A, const int N, int* ptr);
/* The function makes a search on positive int array A with size N and saves the index of the element
with the maximum value to the memory pointed by ptr. You can assume that array has at least one
element. */
// You are allowed to make only 1 pointer declaration.

int** arrayWithLargerMax1(int** A, int** B, const int N);
// A and B point to positive int arrays with size N. The function can only call the function addressOfMax.
/* The function returns the address of the array pointed by B if its largest element is larger than the largest
element of A. Otherwise, it returns the address of the array pointed by A */
// You are allowed to make only 2 pointer declarations. You are not allowed to use loops.

int** arrayWithLargerMax2(int** A, int** B, const int N);
// A and B point to positive int arrays with size N. The function can only call the function indexOfMax.
/* The function returns the address of the array pointed by B if its largest element is larger than the largest
element of A. Otherwise, it returns the address of the array pointed by A */
// You are allowed to make only 2 pointer declarations. You are not allowed to use loops.

void sort(int** A, const int M, const int N);
// A is an array of pointers with size M. Each element of A points to a positive int array with size N.
/* The function rearranges the elements of A using below sorting algorithm so that the arrays will be
sorted from largest to smallest according to their largest elements. */
// You are allowed to make only 2 variable declarations. You are allowed to use only 2 loops.

int main(int argc, char* argv[]);
// The function gets positive integers M, N from the user.
/* It creates an array of pointers (A) with size M, whose each element points to a positive int array with
size N. */
// Assume program takes M*N command line arguments and each argument consists of only digits.
/* In the given order, the function obtains the int equivalent of each argument using str2int and saves it
to A. */
// The function calls sort for A and displays each array of A before exit.

Sorting Algorithm:
FOR i = 1 to (M-1)
              j = i
     REPEAT
               Call arrayWithLargerMax1/2 for (j-1)-th and j-th array, use its return value for the following
                                  If max of j-th array is larger swap A[j-1] and A[j] using swap.
                                  If max of j-th array is not larger, break to exit inner loop.
      UNTIL j is 0

